.btn {
  appearance: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4em;
  border: 0;
  border-radius: 1000px;
  background: var(--c-blue);
  color: var(--c-lavender);
  font: 600 18px/1 var(--f-text);
